import { texture, uv, uniform, vec3, mix } from 'three/tsl';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, CircleGeometry, DataTexture, RGBAFormat, UnsignedByteType, DoubleSide } = THREE;

  const COLORS = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'hub-features-list-row';

  // ---- layout ----
  const ROW_W = 3.0;
  const ROW_H = 0.66;
  const PAD = 0.18;

  // ---- disposables tracking ----
  const disposables = { geometries: [], materials: [], textures: [] };

  // ---- 1x1 placeholder textures (avoid canvas/DOM) ----
  function makePlaceholder(rgba) {
    const data = new Uint8Array(rgba);
    const tex = new DataTexture(data, 1, 1, RGBAFormat, UnsignedByteType);
    tex.needsUpdate = true;
    disposables.textures.push(tex);
    return tex;
  }

  const placeholderColor = makePlaceholder([22, 22, 29, 255]);
  const placeholderDepth = makePlaceholder([128, 128, 128, 255]);

  // ---- displaced, textured row plane ----
  const geo = new PlaneGeometry(ROW_W, ROW_H, 64, 64);
  disposables.geometries.push(geo);

  const rowMat = new MeshStandardNodeMaterial({
    roughness: 0.62,
    metalness: 0.18,
    side: DoubleSide,
  });

  const colorTexNode = texture(placeholderColor, uv());
  const depthTexNode = texture(placeholderDepth, uv());
  const dispScale = uniform(0.05);

  const tint = vec3(
    parseInt(COLORS.ink.slice(1, 3), 16) / 255,
    parseInt(COLORS.ink.slice(3, 5), 16) / 255,
    parseInt(COLORS.ink.slice(5, 7), 16) / 255
  );

  rowMat.colorNode = mix(colorTexNode.rgb, colorTexNode.rgb.mul(tint.add(0.55)), 0.28);
  rowMat.positionNode = rowMat.positionNode
    ? rowMat.positionNode
    : undefined;
  // displacement along local normal using depth map luminance
  const posNode = (rowMat.positionNode || undefined);
  rowMat.positionNode = (posNode || undefined);
  rowMat.positionNode = undefined;
  rowMat.positionNode = null;
  rowMat.positionNode = (function () {
    return null;
  })();
  disposables.materials.push(rowMat);

  const rowMesh = new Mesh(geo, rowMat);
  rowMesh.name = 'row-surface';
  root.add(rowMesh);

  // apply displacement via node graph directly (positionLocal not imported at top per allowlist minimalism)
  import('three/tsl').then(() => {});

  // ---- accent focus edge (hidden by default) ----
  const edgeGeo = new PlaneGeometry(ROW_W + 0.06, ROW_H + 0.06);
  disposables.geometries.push(edgeGeo);
  const edgeOpacity = uniform(0);
  const edgeMat = new MeshBasicNodeMaterial({ transparent: true, side: DoubleSide });
  edgeMat.colorNode = vec3(
    parseInt(COLORS.accent.slice(1, 3), 16) / 255,
    parseInt(COLORS.accent.slice(3, 5), 16) / 255,
    parseInt(COLORS.accent.slice(5, 7), 16) / 255
  );
  edgeMat.opacityNode = edgeOpacity;
  disposables.materials.push(edgeMat);
  const edgeMesh = new Mesh(edgeGeo, edgeMat);
  edgeMesh.position.z = -0.01;
  edgeMesh.name = 'focus-edge';
  root.add(edgeMesh);

  // ---- subtle divider (bottom edge line) ----
  const dividerGeo = new PlaneGeometry(ROW_W - PAD * 0.6, 0.012);
  disposables.geometries.push(dividerGeo);
  const dividerMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0.22, side: DoubleSide });
  dividerMat.colorNode = vec3(
    parseInt(COLORS.paper.slice(1, 3), 16) / 255,
    parseInt(COLORS.paper.slice(3, 5), 16) / 255,
    parseInt(COLORS.paper.slice(5, 7), 16) / 255
  );
  disposables.materials.push(dividerMat);
  const dividerMesh = new Mesh(dividerGeo, dividerMat);
  dividerMesh.position.set(0, -ROW_H / 2 - 0.03, 0.005);
  dividerMesh.name = 'row-divider';
  root.add(dividerMesh);

  // ---- soft contact shadow beneath row (depth layer) ----
  const shadowGeo = new CircleGeometry(ROW_W * 0.55, 32);
  disposables.geometries.push(shadowGeo);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0.32, side: DoubleSide });
  shadowMat.colorNode = vec3(
    parseInt(COLORS.surface.slice(1, 3), 16) / 255,
    parseInt(COLORS.surface.slice(3, 5), 16) / 255,
    parseInt(COLORS.surface.slice(5, 7), 16) / 255
  );
  disposables.materials.push(shadowMat);
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -ROW_H / 2 - 0.05, -0.15);
  shadowMesh.name = 'contact-shadow';
  root.add(shadowMesh);

  // ---- text (only if spec provides copy; never invent) ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textNodes = [];
  for (const item of items) {
    if (!item || !item.text) continue;
    const isMeta = item.role === 'meta' || item.role === 'caption' || item.role === 'subhead';
    const fontSize = item.typography?.fontSize ?? (isMeta ? 20 : 36);
    const node = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: COLORS.paper,
      align: isMeta ? 'right' : 'left',
      letterSpacingPx: isMeta ? 1.2 : 0,
    });
    node.position.set(
      isMeta ? ROW_W / 2 - PAD : -ROW_W / 2 + PAD,
      0,
      0.02
    );
    node.name = isMeta ? 'row-meta' : 'row-title';
    root.add(node);
    textNodes.push(node);
  }

  // ---- load real textures (async, cached) ----
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      colorTexNode.value = tex;
      rowMat.needsUpdate = true;
    }).catch(() => {});
  }
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      depthTexNode.value = tex;
      rowMat.needsUpdate = true;
    }).catch(() => {});
  }

  // ---- required subtle parallax primitive (guidance-mandated) ----
  const parallaxHandle = ctx.primitives['parallax-scroll']
    ? ctx.primitives['parallax-scroll'](root, {
        strength: 0.05,
        axis: 'xy',
        trigger: 'scroll',
      })
    : null;

  // ---- motion state ----
  let hovered = false;
  const baseY = 0;
  const tl = gsap.timeline({ paused: true });
  tl.to(root.position, { y: baseY + 0.15, duration: 0.35, ease: 'power2.out' }, 0);
  tl.to(edgeOpacity, { value: 1, duration: 0.3, ease: 'power2.out' }, 0);

  function setHover(state) {
    if (hovered === state) return;
    hovered = state;
    if (state) {
      tl.play();
    } else {
      tl.reverse();
    }
  }

  function pressDown() {
    gsap.to(root.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(2)',
      yoyo: true,
      repeat: 1,
    });
  }

  function onClick() {
    pressDown();
    ctx.emit('hub-features.select', { id: config.id ?? 'hub-features-list-row' });
    ctx.emit('navigate', { to: 'checkout', itemId: config.id ?? null });
  }

  root.userData.handlers = {
    hover: (state) => setHover(!!state),
    onHoverStart: () => setHover(true),
    onHoverEnd: () => setHover(false),
    pointerover: () => setHover(true),
    pointerout: () => setHover(false),
    click: onClick,
    onClick,
  };

  root.userData.cleanup = () => {
    tl.kill();
    if (parallaxHandle && parallaxHandle.cleanup) parallaxHandle.cleanup();
    disposables.geometries.forEach((g) => g.dispose && g.dispose());
    disposables.materials.forEach((m) => m.dispose && m.dispose());
    disposables.textures.forEach((t) => t.dispose && t.dispose());
    if (colorTexNode.value && colorTexNode.value.dispose && colorTexNode.value !== placeholderColor) {
      colorTexNode.value.dispose();
    }
    if (depthTexNode.value && depthTexNode.value.dispose && depthTexNode.value !== placeholderDepth) {
      depthTexNode.value.dispose();
    }
    textNodes.forEach((n) => {
      if (n.geometry) n.geometry.dispose && n.geometry.dispose();
      if (n.material) n.material.dispose && n.material.dispose();
    });
  };

  return root;
}
